def test_map_and_deploy_share_one_wait_helper():
    # Symmetric application: one timer per step, no stage-specific copy that
    # could drift back to an unbounded hold.
    assert M._boss_companion_wait_expired is D._boss_companion_wait_expired is orders._boss_companion_wait_expired
    assert M.BOSS_COMPANION_WAIT_TICKS == orders.BOSS_COMPANION_WAIT_TICKS


def _reactivate(mem, order):
    # A hold clears active/context; the orchestrator re-activates the pending
    # step on a later observation before deploy_step runs again.
    D._plan_region(mem)['active'] = order['step']
    D._plan_region(mem)['orders'][order['step']] = 'pending'


def test_general_list_companion_hold_expires():
    order, mem = boss_memory()
    screen = selected_list([D.NAME])

    _reactivate(mem, order)
    assert D.deploy_step(screen, mem) == [D.pad('b'), D.pad('b')]
    assert mem['_records'][-1]['decision'] == 'boss_companion_required'

    mem['tick'] += orders.BOSS_COMPANION_WAIT_TICKS - 1
    _reactivate(mem, order)
    assert D.deploy_step(screen, mem) == [D.pad('b'), D.pad('b')]
    assert mem['_records'][-1]['decision'] == 'boss_companion_required'

    mem['tick'] += 1
    _reactivate(mem, order)
    D.deploy_step(screen, mem)
    decisions = [r['decision'] for r in mem['_records']]
    assert 'boss_companion_timeout' in decisions
    assert decisions[-1] != 'boss_companion_required'


