def test_general_list_timeout_receipt_survives_card_select_stage():
    order, mem = boss_memory()
    step = order['step']
    _reactivate(mem, order)
    assert D.deploy_step(selected_list([D.NAME]), mem) == [D.pad('b'), D.pad('b')]

    mem['tick'] += orders.BOSS_COMPANION_WAIT_TICKS
    _reactivate(mem, order)
    D.deploy_step(selected_list([D.NAME]), mem)
    flow_state = orders._flow(mem)
    assert flow_state['boss_companion_wait_expired'][step] is True
    assert step not in flow_state.get('boss_companion_wait', {})
    assert _plan_region(mem)['sortie_general'][step] == D.NAME
    assert [r['decision'] for r in mem['_records']].count('boss_companion_timeout') == 1

    # The same order now reaches card selection. Its expired receipt must
    # bypass the hold without starting another 200-tick window.
    _reactivate(mem, order)
    D._plan_region(mem).setdefault('sortie_general', {})[step] = D.NAME
    D.deploy_step(actor_panel(measured_card_select(), D.NAME), mem)
    assert flow_state['boss_companion_wait_expired'][step] is True
    assert step not in flow_state.get('boss_companion_wait', {})
    assert [r['decision'] for r in mem['_records']].count('boss_companion_timeout') == 1
    assert [r['decision'] for r in mem['_records']].count('boss_companion_required') == 1

def test_strategy_companion_source_gate_expires():
    # Chapter 9 has no static chart.orders() because its boss moves; use a
    # non-moving boss chapter to exercise the same readiness gate deterministically.
    chapter = 10
    home = chart.home_castle(chapter)
    boss = chart.boss_castle(chapter)
    order = next(o for o in chart.orders(chapter) if o['target'] == boss)
    # The source roster is known but contains no eligible companion. Chapter-4
    # seasonal sites intentionally retain their separate measured egg-holder gate.
    garrison = {castle: [] for castle in chart.CASTLE_NAMES[chapter]}
    garrison[home] = [chart.HERO]
    mem = {'chapter': chapter, 'tick': 100, 'captured':
           [c for c in chart.CASTLE_NAMES[chapter] if c not in (home, boss)],
           'lost': [], 'orders': {}, 'garrison': garrison,
           'egg_types': {}, 'egg_uses': {}, 'general_location_unknown': [], '_records': []}
    assert orders._boss_companion_source(order, mem) is None

    assert not orders._ready(order, mem)
    mem['tick'] += orders.BOSS_COMPANION_SOURCE_WAIT_TICKS - 1
    assert not orders._ready(order, mem)
    mem['tick'] += 1
    assert orders._ready(order, mem)

    timed_out = [r for r in mem['_records']
                 if r['decision'] == 'boss_companion_source_timeout']
    assert len(timed_out) == 1
    assert timed_out[0]['observed_metric']['waited_ticks'] == orders.BOSS_COMPANION_SOURCE_WAIT_TICKS
    # Repeated readiness checks reuse the same expiry receipt and do not
    # emit a second timeout or begin another source-wait window.
    assert orders._ready(order, mem) is True
    assert len([r for r in mem['_records']
                if r['decision'] == 'boss_companion_source_timeout']) == 1
    _plan_region(mem)['active'] = order['step']
    orders._finish_order(mem, 'failed', deviation_reason='test cleanup', reason='test cleanup')
    assert order['step'] not in mem.get('boss_companion_source_wait_expired', {})


def test_stalled_castle_jump_fallback_is_bounded_and_retires_the_step():
    mem = {'tick': 100,
           'plan': {'active': 'J1', 'orders': {'J1': 'pending'}},
           '_records': []}
    jump = {'step': 'J1', 'source': 'カラ', 'mode': 'source',
            'scrolls': 8, 'scroll_stall': M.CASTLE_JUMP_SCROLL_STALL}
    rows = [(0, 'カラ')]
    screen = Screen([], None, '', kind='map')

    # Below the bound the resume marker survives (the original #4338 fix).
    for _ in range(M.CASTLE_JUMP_ABANDON - 1):
        assert M._castle_jump_y_fallback(screen, mem, jump, rows) == [M.pad('b')]
        assert mem['castle_jump_y']['source'] == 'カラ'
        assert mem['plan']['orders']['J1'] == 'pending'

    assert M._castle_jump_y_fallback(screen, mem, jump, rows) == [M.pad('b')]
    assert mem['plan']['orders']['J1'] == 'failed'
    assert mem['plan']['active'] is None
    assert 'castle_jump_y' not in mem
    decisions = [r['decision'] for r in mem['_records']]
    assert decisions.count('castle_jump_abandoned') == 1
    assert 'castle_jump_y_fallback' in decisions
